"""
Benchmarks of the analysis layer of an algorithm.

The sequences are written out in full rather than generated at run time,
so that saved runs stay comparable. The ids of the parametrized cases are
the number of moves and serve as comparison keys. Run them with:

    pytest benchmarks --no-cov --benchmark-autosave
    pytest benchmarks --no-cov --benchmark-compare
"""
import pytest
from pytest_benchmark.fixture import BenchmarkFixture

from cubing_algs.algorithm import Algorithm

T_PERM = "R U R' U' R' F R2 U' R' U' R U R' F'"

# Generated by scramble with the seed 2026
RANDOM_40 = (
    "F U2 L2 B2 D' R' U B D L2 B D L2 D2 L' D L' U R D R' F' U' R' "
    "B' R D' L' D' F2 U L U' F2 U2 L D2 L2 D' R'"
)

# Generated by scramble with the seed 80, the length of a full solve
RANDOM_80 = (
    "U2 L B2 D2 L U2 F2 L2 B U2 R B2 L U B R B U R2 B2 D R F2 L' D R2 "
    "F2 U F2 U2 B R2 D' F U' F' R' U2 R' D' R D2 R F2 L2 U' F' U2 B D "
    "R U2 L' D2 R' U B' L' B2 U2 L2 D2 R B' U F' U2 L' D' F2 D2 B' R "
    "B2 R B U R' D' R'"
)

SEQUENCES = {
    '14': T_PERM,
    '40': RANDOM_40,
    '80': RANDOM_80,
}


@pytest.mark.parametrize('length', ['14', '40', '80'])
def test_structure(benchmark: BenchmarkFixture, length: str) -> None:
    """Commutator and conjugate detection, superlinear in the length."""
    algorithm = Algorithm.parse_moves(SEQUENCES[length])
    benchmark(lambda: algorithm.structure)


@pytest.mark.parametrize('length', ['14', '80'])
def test_to_dict(benchmark: BenchmarkFixture, length: str) -> None:
    """The complete analysis, as exported by the CLI info command."""
    algorithm = Algorithm.parse_moves(SEQUENCES[length])
    benchmark(algorithm.to_dict)


def test_ergonomics(benchmark: BenchmarkFixture) -> None:
    """Ergonomics of a 14 moves algorithm."""
    algorithm = Algorithm.parse_moves(T_PERM)
    benchmark(lambda: algorithm.ergonomics)


def test_impacts(benchmark: BenchmarkFixture) -> None:
    """Impacts of a 14 moves algorithm on the cube."""
    algorithm = Algorithm.parse_moves(T_PERM)
    benchmark(algorithm.impacts)


def test_memory(benchmark: BenchmarkFixture) -> None:
    """Memorization difficulty of a 14 moves algorithm."""
    algorithm = Algorithm.parse_moves(T_PERM)
    benchmark(lambda: algorithm.memory)
